import json
from pathlib import Path


def load_payload(path: Path):
    """Read a UTF-8 JSON payload. Only a top-level object or array is legal."""
    path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise ValueError("cannot read payload: %s" % path) from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON payload: %s" % path) from exc
    if isinstance(data, (dict, list)):
        return data
    raise ValueError("top-level JSON value must be an object or array: %s" % path)

