import math


def _finite_check(node):
    """Reject NaN/Infinity anywhere in a nested JSON structure."""
    if isinstance(node, float):
        if not math.isfinite(node):
            raise ValueError("non-finite number in payload")
        return
    if isinstance(node, dict):
        for value in node.values():
            _finite_check(value)
        return
    if isinstance(node, list):
        for value in node:
            _finite_check(value)


def _unwrap(payload):
    """Unwrap an upstream component envelope iff the key set is exactly
    {'name','result'}; otherwise return the object unchanged."""
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _is_bool(value):
    return isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str) and value.strip() != ""


def _field_name(value):
    if not _is_text(value):
        raise ValueError("field name must be non-empty text")
    return value.strip()


def _read_field(raw):
    if not isinstance(raw, dict):
        raise ValueError("field must be an object")
    name = _field_name(raw.get("name"))
    if "type" not in raw or raw["type"] not in ("int", "float", "str", "bool"):
        raise ValueError("field type must be int/float/str/bool")
    if "required" not in raw or not _is_bool(raw["required"]):
        raise ValueError("field required must be a boolean")
    return {
        "name": name,
        "type": raw["type"],
        "required": raw["required"],
        "has_default": "default" in raw,
    }


def _read_fields(value, label):
    if not isinstance(value, list):
        raise ValueError(label + " must be a list")
    fields = [_read_field(item) for item in value]
    names = [f["name"] for f in fields]
    if len(set(names)) != len(names):
        raise ValueError("duplicate field name in " + label)
    return fields


def _schema_compare(old_fields, new_fields):
    old_by_name = {f["name"]: f for f in old_fields}
    new_by_name = {f["name"]: f for f in new_fields}
    changes = []
    compatible = True
    for name in sorted(set(old_by_name) | set(new_by_name)):
        old = old_by_name.get(name)
        new = new_by_name.get(name)
        if old is not None and new is None:
            changes.append({"field": name, "code": "removed", "breaking": True})
            compatible = False
        elif old is None and new is not None:
            breaking = new["required"] and not new["has_default"]
            changes.append({"field": name, "code": "added", "breaking": breaking})
            if breaking:
                compatible = False
        else:
            if old["type"] != new["type"]:
                breaking = not (old["type"] == "int" and new["type"] == "float")
                changes.append({"field": name, "code": "type", "breaking": breaking})
                if breaking:
                    compatible = False
            if not old["required"] and new["required"]:
                breaking = not new["has_default"]
                changes.append(
                    {"field": name, "code": "required", "breaking": breaking}
                )
                if breaking:
                    compatible = False
    return compatible, changes


def _has_cycle(edges):
    nodes = set(edges.keys()) | set(edges.values())
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in nodes}

    def dfs(node):
        color[node] = GRAY
        nxt = edges.get(node)
        if nxt is not None:
            if color.get(nxt, WHITE) == GRAY:
                return True
            if color.get(nxt, WHITE) == WHITE and dfs(nxt):
                return True
        color[node] = BLACK
        return False

    for node in nodes:
        if color[node] == WHITE and dfs(node):
            return True
    return False


def _terminal(name, edges):
    seen = set()
    current = name
    while current in edges:
        if current in seen:
            raise ValueError("rename cycle detected")
        seen.add(current)
        current = edges[current]
    return current


def transform(payloads, contract):
    for payload in payloads:
        _finite_check(payload)

    data = _unwrap(payloads[0])
    if not isinstance(data, dict):
        raise ValueError("schema_migration input must be an object")

    if "old" not in data or "new" not in data or "renames" not in data:
        raise ValueError("schema_migration input requires old/new/renames")

    old_fields = _read_fields(data["old"], "old")
    new_fields = _read_fields(data["new"], "new")

    renames_raw = data["renames"]
    if not isinstance(renames_raw, list):
        raise ValueError("renames must be a list")

    edges = {}
    seen_from = set()
    for item in renames_raw:
        if not isinstance(item, dict):
            raise ValueError("rename must be an object")
        if "from" not in item or "to" not in item:
            raise ValueError("rename requires from/to")
        src = _field_name(item["from"])
        dst = _field_name(item["to"])
        if src in seen_from:
            raise ValueError("duplicate rename from: " + src)
        seen_from.add(src)
        edges[src] = dst

    if _has_cycle(edges):
        raise ValueError("rename cycle detected")

    renamed_old = []
    terminals = []
    for field in old_fields:
        if field["name"] in edges:
            terminal = _terminal(field["name"], edges)
        else:
            terminal = field["name"]
        terminals.append(terminal)
        renamed_old.append(
            {
                "name": terminal,
                "type": field["type"],
                "required": field["required"],
                "has_default": field["has_default"],
            }
        )

    if len(set(terminals)) != len(terminals):
        raise ValueError("different old fields resolve to the same terminal name")

    compatible, changes = _schema_compare(renamed_old, new_fields)
    field_map = {
        old_fields[i]["name"]: terminals[i] for i in range(len(old_fields))
    }

    return {
        "name": contract["name"],
        "result": {
            "compatible": compatible,
            "changes": changes,
            "field_map": field_map,
        },
    }

