def transform(payloads, contract):
    for payload in payloads:
        _finite_check(payload)

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError("quorum_cutover input must be an object")
    for key in ("partitions", "candidates", "budget"):
        if key not in raw:
            raise ValueError("quorum_cutover input requires " + key)
    if not isinstance(raw["partitions"], list):
        raise ValueError("partitions must be a list")
    if not isinstance(raw["candidates"], list):
        raise ValueError("candidates must be a list")
    if not _is_int(raw["budget"]) or raw["budget"] < 0:
        raise ValueError("budget must be an int >= 0")

    partitions = []
    partition_ids = set()
    for item in raw["partitions"]:
        partition = _read_partition(item)
        if partition["id"] in partition_ids:
            raise ValueError("duplicate partition id: " + partition["id"])
        partition_ids.add(partition["id"])
        partitions.append(partition)

    candidates = []
    candidate_ids = set()
    replica_seen = set()
    for item in raw["candidates"]:
        candidate = _read_candidate(item)
        if candidate["id"] in candidate_ids:
            raise ValueError("duplicate candidate id: " + candidate["id"])
        candidate_ids.add(candidate["id"])
        if candidate["replica"] in replica_seen:
            raise ValueError("duplicate candidate replica: " + candidate["replica"])
        replica_seen.add(candidate["replica"])
        candidates.append(candidate)

    # Consume the two upstream component results.
    schema_compatible = _read_schema_result(_unwrap(payloads[1]))
    replay_replicas = _read_replay_result(_unwrap(payloads[2]))

    partitions_by_id = {p["id"]: p for p in partitions}

    resolved = []
    for candidate in candidates:
        replica = replay_replicas.get(candidate["replica"])
        if replica is None:
            raise ValueError("unknown candidate replica: " + candidate["replica"])
        if replica["shard"] not in partitions_by_id:
            raise ValueError("unknown replica shard: " + replica["shard"])
        partition = partitions_by_id[replica["shard"]]
        eligible = (
            replica["sha256"] == partition["target_sha256"]
            and replica["applied_offset"] >= partition["target_offset"]
        )
        resolved.append(
            {
                "id": candidate["id"],
                "cost": candidate["cost"],
                "partition": partition["id"],
                "host": replica["host"],
                "eligible": eligible,
            }
        )

    if not schema_compatible:
        return {
            "name": contract["name"],
            "result": {
                "blocked": True,
                "selected": [],
                "partitions": [],
                "value": 0,
                "cost": 0,
            },
        }

    eligible_candidates = [c for c in resolved if c["eligible"]]

