# Enumerate subsets exactly (candidate count is bounded by 14).
best = (0, 0, [])  # (value, cost, sorted selected ids)

n = len(eligible_candidates)
for mask in range(1 << n):
    selected_ids = []
    total_cost = 0
    per_partition = {}
    valid = True
    for i in range(n):
        if mask & (1 << i):
            cand = eligible_candidates[i]
            selected_ids.append(cand["id"])
            total_cost += cand["cost"]
            state = per_partition.setdefault(
                cand["partition"], {"count": 0, "hosts": set()}
            )
            state["count"] += 1
            if cand["host"] in state["hosts"]:
                valid = False
                break
            state["hosts"].add(cand["host"])
    if not valid or total_cost > raw["budget"]:
        continue

    satisfied = []
    value = 0
    for pid, state in per_partition.items():
        if state["count"] == 0:
            continue
        if state["count"] != partitions_by_id[pid]["quorum"]:
            valid = False
            break
        satisfied.append(pid)
        value += partitions_by_id[pid]["value"]
    if not valid:
        continue

    selected_ids.sort()
    candidate_solution = (value, total_cost, selected_ids)
    if _better(best, candidate_solution):
        best = candidate_solution

value, cost, selected = best
satisfied_partitions = []
if selected:
    selected_by_id = {c["id"]: c for c in eligible_candidates}
    for cid in selected:
        pid = selected_by_id[cid]["partition"]
        if pid not in satisfied_partitions:
            satisfied_partitions.append(pid)
    satisfied_partitions.sort()

return {
    "name": contract["name"],
    "result": {
        "blocked": False,
        "selected": selected,
        "partitions": satisfied_partitions,
        "value": value,
        "cost": cost,
    },
}

