import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def discover_components():
    components = {}
    for path in ROOT.iterdir():
        if not path.is_dir():
            continue
        contract_path = path / "contract.json"
        render_path = path / "render.py"
        if not (contract_path.is_file() and render_path.is_file()):
            continue
        contract = json.loads(contract_path.read_text(encoding="utf-8"))
        components[contract["name"]] = {
            "dir": path.name,
            "inputs": contract["inputs"],
            "output": contract["output"],
        }
    return components


def execution_order(components):
    by_output = {
        components[name]["output"]: name for name in components
    }
    order = []
    done = set()

    def visit(name, stack):
        if name in done:
            return
        if name in stack:
            raise ValueError("cyclic component dependency")
        stack.add(name)
        for input_path in components[name]["inputs"]:
            dep = by_output.get(input_path)
            if dep is not None and dep != name:
                visit(dep, stack)
        stack.remove(name)
        done.add(name)
        order.append(name)

    for name in components:
        visit(name, set())
    return order


def main():
    components = discover_components()
    if not components:
        raise ValueError("no component packages found")

    for name in execution_order(components):
        render_path = ROOT / components[name]["dir"] / "render.py"
        subprocess.run(
            [sys.executable, str(render_path)],
            cwd=ROOT,
            check=True,
            timeout=60,
        )

    subprocess.run(
        [sys.executable, str(ROOT / "integrate.py")],
        cwd=ROOT,
        check=True,
        timeout=60,
    )
    subprocess.run(
        [sys.executable, str(ROOT / "final_report.py")],
        cwd=ROOT,
        check=True,
        timeout=60,
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

